201	export type LaneReadings = Readonly<{
202		removedSymbolSurfaces: readonly RootSurfaceReading[];
203		moduleClassSurfaces: readonly ModuleClassSurfaceReading[];
204		rxjsPatchDiagnostics: readonly RxjsPatchDiagnosticReading[];
