216	/**
217	 * The names an `export { … } from '…'` declaration line publishes, with an
218	 * `as` rename resolved to the exported name. Declaration files of this shape —
219	 * one re-export per line — are what both packages read here publish, and the
220	 * reading is refused as incomplete when it finds none.
221	 */
222	function reExportedNames(source: string): readonly string[] {
223		const names = new Set<string>();
224		for (const line of source.split('\n')) {
225			const text = line.trim();
226			if (!text.startsWith('export {')) continue;
227			const open = text.indexOf('{');
228			const close = text.indexOf('}', open);
229			if (open < 0 || close < 0) continue;
230			for (const part of text.slice(open + 1, close).split(',')) {
231				const name = part.split(' as ').at(-1)?.trim();
232				if (name !== undefined && name !== '') names.add(name);
233			}
234		}
235		return Object.freeze([...names].sort());
236	}
