238	/**
239	 * The leading run of `text` that stops before any of `delimiters`. Written as a
240	 * scan rather than a split so this file introduces no regular expression.
241	 */
242	function headToken(text: string, delimiters: string): string {
243		for (let index = 0; index < text.length; index += 1)
244			if (delimiters.includes(text[index] as string)) return text.slice(0, index);
245		return text;
246	}
