248	/** The installed version of a package, or `unknown` when it cannot be read. */
249	async function installedVersion(modules: string, owner: string): Promise<string> {
250		try {
251			const manifest = JSON.parse(
252				await readFile(path.join(modules, owner, 'package.json'), 'utf8'),
253			) as Readonly<{ version?: unknown }>;
254			return typeof manifest.version === 'string' ? manifest.version : 'unknown';
255		} catch {
256			return 'unknown';
257		}
258	}
