260	/**
261	 * What the installed declaration publishes as statics on one exported class.
262	 *
263	 * The reading is of the class body in the package's own `index.d.ts`: the lines
264	 * between `declare class X {` and the brace that closes it, reduced to the
265	 * `static` members. `complete` is false when the class declaration is not found
266	 * at all, because a reading that found no class proves no member absent.
267	 */
268	export async function readModuleClassSurface(
269		tree: string,
270		packageName: string,
271		symbol: string,
272	): Promise<ModuleClassSurfaceReading> {
273		const modules = path.join(tree, 'node_modules');
274		const version = await installedVersion(modules, packageName);
275		const declaration = path.join(modules, packageName, 'index.d.ts');
276		const statics: string[] = [];
277		let complete = false;
278		if (existsSync(declaration)) {
279			const lines = (await readFile(declaration, 'utf8')).split('\n');
280			let inside = false;
281			for (const line of lines) {
282				const text = line.trim();
283				if (!inside) {
284					if (!text.startsWith('export declare class ') && !text.startsWith('declare class '))
285						continue;
286					const named = headToken(
287						text.slice(text.indexOf('class ') + 'class '.length),
288						' <{',
289					);
290					if (named !== symbol) continue;
291					inside = true;
292					complete = true;
293					continue;
294				}
295				if (text.startsWith('}')) break;
296				if (!text.startsWith('static ')) continue;
297				const member = headToken(text.slice('static '.length), ' (:<;=?');
298				if (member !== '') statics.push(member);
299			}
300		}
301		return Object.freeze({
302			package: packageName,
303			version,
304			symbol,
305			statics: Object.freeze([...new Set(statics)].sort()),
306			complete,
307		});
308	}
