336	/**
337	 * The `TS2339` diagnostics an Angular build log states, per file, reduced to the
338	 * ones whose receiver the compiler named as an RxJS type.
339	 *
340	 * The filter is the honest part. A `TS2339` on a DOM interface is a different
341	 * capability's diagnostic and feeding it here would refuse the whole module for
342	 * a reason that is not about RxJS; the receiver type is the compiler's own
343	 * words, so the separation is read rather than guessed. Positions are the
344	 * compiler's, into the bytes it compiled — which is why the capability that
345	 * takes them re-places every one of them before it edits anything.
346	 */
347	export function readRxjsPatchDiagnostics(log: string): readonly RxjsPatchDiagnosticReading[] {
348		const byPath = new Map<string, PatchedCallDiagnostic[]>();
349		for (const line of log.split('\n')) {
350			const text = line.trim();
351			const marker = ' - error TS2339: Property ';
352			const at = text.indexOf(marker);
353			if (at < 0) continue;
354			const head = text.slice(0, at);
355			const tail = text.slice(at + marker.length);
356			const property = tail.split("'")[1];
357			const receiver = tail.split("on type '")[1]?.split("'")[0];
358			if (property === undefined || receiver === undefined) continue;
359			const bare = receiver.startsWith('typeof ') ? receiver.slice('typeof '.length) : receiver;
360			const head0 = bare.split('<')[0] ?? bare;
361			if (!RXJS_RECEIVER_TYPES.includes(head0)) continue;
362			const parts = head.replace('Error: ', '').split(':');
363			const column = Number(parts.at(-1));
364			const lineNumber = Number(parts.at(-2));
365			const file = parts.slice(0, -2).join(':').trim();
366			if (!Number.isInteger(column) || !Number.isInteger(lineNumber) || file === '') continue;
367			const list = byPath.get(file) ?? [];
368			list.push(
369				Object.freeze({ line: lineNumber, column, property, receiverType: receiver }),
370			);
371			byPath.set(file, list);
372		}
373		return Object.freeze(
374			[...byPath.entries()]
375				.sort((left, right) => (left[0] < right[0] ? -1 : 1))
376				.map((entry) => Object.freeze({ path: entry[0], diagnostics: Object.freeze(entry[1]) })),
377		);
378	}
