564		removedSpecifier: string,
565	): Promise<RootSurfaceReading> {
566		const modules = path.join(tree, 'node_modules');
567		const owner = successorSpecifier.startsWith('@')
568			? successorSpecifier.split('/').slice(0, 2).join('/')
569			: (successorSpecifier.split('/')[0] ?? successorSpecifier);
570		let version = 'unknown';
571		try {
572			const manifest = JSON.parse(
573				await readFile(path.join(modules, owner, 'package.json'), 'utf8'),
574			) as Readonly<{ version?: unknown }>;
575			if (typeof manifest.version === 'string') version = manifest.version;
576		} catch {
